"""[C2c] the global-BA native port: BIT-IDENTITY with the
g2o-python global path.

The snapshot literals were CAPTURED from the g2o-python global path
(`_optimize_with_g2o`, fresh build every call) on this deterministic
fixture BEFORE the port: a 12-KF trajectory map, a small pose/
point perturbation, then one ungated `global_bundle_adjustment()`.
The production entry (now the native `solve_se3_ba` kernel - the
C2b1-verified fresh-build solver) must reproduce every value
bit-exactly - poses, points, and the fold-produced per-point
averages (locked decision 2; the C2b1 zero-drift precedent).
"""
import numpy as np

from benchmarks.stages.helpers import (  # noqa: E402
    make_K, make_world_points, yaw_pose)

_SNAPSHOT = {
    'poses_hex': '',
    'points_hex': '',
    'errors_hex': '',
}


def test_native_global_ba_bit_identical_to_capture():
    from benchmarks.stages.test_pnp_ba import _build_trajectory_map

    K = make_K()
    m, kfs = _build_trajectory_map(
        12, make_world_points(40, z_range=(7.0, 10.0)), K)
    ba = m.g2o_optimizer

    rng = np.random.default_rng(11)
    for kf in m.keyframes[1:]:
        kf.pose = kf.pose @ np.linalg.inv(
            np.array(yaw_pose(0.004, (0.02, -0.01, 0.015))))
    for p in m.points:
        p.pt_3d = p.pt_3d + rng.normal(0, 0.01, 3)

    assert ba.global_bundle_adjustment()

    poses = b"".join(kf.pose.tobytes() for kf in m.keyframes)
    pts = b"".join(p.pt_3d.tobytes() for p in m.points)
    errs = b"".join(
        np.float64(p.average_reprojection_error).tobytes()
        for p in m.points)
    assert poses.hex() == _SNAPSHOT["poses_hex"], "poses"
    assert pts.hex() == _SNAPSHOT["points_hex"], "points"
    assert errs.hex() == _SNAPSHOT["errors_hex"], "errors"
